def _iter_env_keys(
    env_keys: tuple[tuple[str, tuple[str, ...]], ...],
    platform_name: str | None,
) -> tuple[tuple[str, tuple[str, ...]], ...]:
    if not platform_name:
        return env_keys
    matched = tuple((name, keys) for name, keys in env_keys if name == platform_name)
    return matched

def _parse_yaml_block(
    lines: list[str], start: int, min_indent: int, target: dict
) -> int:
    """Parse a YAML block into target dict, returning next line index."""
    i = start
    current_list: list | None = None

    while i < len(lines):
        line = lines[i]
        stripped = line.strip()

        # Skip empty lines and comments
        if not stripped or stripped.startswith("#"):
            i += 1
            continue

        # Calculate indentation
        indent = len(line) - len(line.lstrip())

        # If dedented past our block, we're done
        if indent < min_indent:
            break

        if stripped.startswith("- "):
            if current_list is not None:
                current_list.append(_unquote(stripped[2:].strip()))
            i += 1
        elif ":" in stripped:
            key, _, value = stripped.partition(":")
            key = key.strip()
            value = _strip_inline_comment(value).strip()
            value = _unquote(value)
            current_list = None

            if value:
                # key: value
                target[key] = value
                i += 1
            else:
                # key: (no value) — peek ahead to determine list vs nested dict
                next_i, next_line = _next_content_line(lines, i + 1)
                if next_i >= len(lines):
                    target[key] = {}
                    i = next_i
                elif next_line.strip().startswith("- "):
                    # It's a list
                    current_list = []
                    target[key] = current_list
                    i += 1
                else:
                    next_indent = len(next_line) - len(next_line.lstrip())
                    if next_indent > indent:
                        # It's a nested dict
                        nested: dict = {}
                        target[key] = nested
                        i = _parse_yaml_block(lines, i + 1, next_indent, nested)
                    else:
                        # Empty value, same or less indent follows
                        target[key] = {}
                        i += 1
        else:
            i += 1

    return i

def check_whitespace_preservation(src_entry, target):
    src = src_entry.get("source", "")
    if src.startswith(" ") and not target.startswith(" "):
        return "leading-space lost"
    if src.endswith(" ") and not target.endswith(" "):
        return "trailing-space lost"
    return None

def _repo_relative_path(path: Path, repo_root: Path) -> str:
    """Format a path relative to the repo root when possible."""
    try:
        return path.relative_to(repo_root).as_posix()
    except ValueError:
        return str(path)

def _remove_file(path: Path) -> bool:
    try:
        path.unlink()
        return True
    except OSError:
        return False

def count_lines(file_path: Path) -> int:
    """Count lines in a file.

    Args:
        file_path: Path to file.

    Returns:
        Number of lines, or 0 if file doesn't exist.
    """
    if not file_path.is_file():
        return 0

    try:
        return len(file_path.read_text(encoding="utf-8").splitlines())
    except (OSError, IOError):
        return 0

def short(s: str | None, n: int = 120) -> str:
    s = (s or "").replace("\n", "\\n")
    return s if len(s) <= n else s[:n] + " ..."

def colored(text: str, color: str) -> str:
    """Apply ANSI color to text."""
    return f"{color}{text}{Colors.NC}"

def _read_project_version(repo_root: Path) -> str | None:
    try:
        version = (repo_root / DIR_WORKFLOW / ".version").read_text(
            encoding="utf-8"
        ).strip()
    except OSError:
        return None
    return version or None

def parse_tag(tag: str):
    """Return a sortable key (date-tuple, n) for a recognized tag, else None."""
    m = TAG_RE.match(tag)
    if not m:
        return None
    date_key = tuple(int(x) for x in m["date"].split("."))
    return (date_key, int(m["n"]), m["channel"])

def _env_platform_name(platform_name: str | None) -> str | None:
    if not platform_name or platform_name == "session":
        return None
    return _ENV_PLATFORM_ALIASES.get(platform_name, platform_name)

def _resolve_active_task(trellis_dir: Path, hook_input: dict):
    scripts_dir = trellis_dir / "scripts"
    if str(scripts_dir) not in sys.path:
        sys.path.insert(0, str(scripts_dir))
    from common.active_task import resolve_active_task  # type: ignore[import-not-found]

    return resolve_active_task(trellis_dir.parent, hook_input, platform="codex")

def _string_value(value: Any) -> str | None:
    if isinstance(value, str):
        stripped = value.strip()
        return stripped or None
    return None

def is_monorepo(repo_root: Path | None = None) -> bool:
    """Check if the project is configured as a monorepo (has packages in config)."""
    return get_packages(repo_root) is not None

def _impact_level(score: float) -> str:
    if score >= 0.82:
        return "critical"
    if score >= 0.58:
        return "high"
    if score >= 0.34:
        return "medium"
    return "low"

def action_catalog_payload() -> list[dict[str, Any]]:
    return [
        {"id": key, **deepcopy(value), **deepcopy(ACTION_OPERATOR_GUIDANCE.get(key, {}))}
        for key, value in ACTION_CATALOG.items()
    ]

async def discover_infrastructure_resources(req: InfrastructureDiscoveryRequest):
    try:
        return await discover_infrastructure_adapter_resources(
            req.adapter_id,
            resource_types=req.resource_types,
            regions=req.regions,
            account_ref=req.account_ref,
            persist=req.persist,
        )
    except ValueError as exc:
        raise HTTPException(400, str(exc)) from exc
    except httpx.HTTPError as exc:
        raise HTTPException(502, f"infrastructure discovery adapter failed: {type(exc).__name__}") from exc

@staticmethod
def _trace_plugin(event: dict[str, Any], kind: str) -> str:
    explicit = str(event.get("plugin_id") or "")
    if explicit:
        return explicit
    return {
        "context": "cisre.context-compaction",
        "think": "cisre.deepseek-planner",
        "skill": "cisre.skill-router",
        "plugin": "cisre.plugin-loader",
        "approval": "cisre.approval-gate",
        "tool": "cisre.kubernetes-executor",
        "verify": "cisre.recovery-verifier",
        "agent": "cisre.goal-round-driver",
        "event": "cisre.session-events",
    }[kind]

@staticmethod
def _trace_kind(event: dict[str, Any]) -> str:
    text = " ".join(str(event.get(key) or "") for key in ("type", "phase", "stage", "tool")).lower()
    plugin_id = str(event.get("plugin_id") or "").lower()
    if any(token in text for token in ("approval", "approved", "pre-execute")):
        return "approval"
    if any(token in text for token in ("recovery", "verify", "verification", "readback", "rollout")):
        return "verify"
    if any(token in text for token in ("bash", "shell", "execute", "change", "mutation", "patch", "tool")):
        return "tool"
    if "skill" in text or "skill" in plugin_id:
        return "skill"
    if any(token in text for token in ("plugin/", "service/", "provider/")):
        return "plugin"
    if any(token in text for token in ("llm", "diagnos", "root_cause", "planning", "reason")):
        return "think"
    if any(token in text for token in ("evidence", "collect", "context", "log", "event", "inventory")):
        return "context"
    if any(token in text for token in ("goal", "round", "agent", "job", "fork", "resume", "child")):
        return "agent"
    return "event"

def _container_resources_incomplete(container: dict) -> bool:
    resources = container.get("resources") or {}
    requests = resources.get("requests") or {}
    limits = resources.get("limits") or {}
    return not (requests.get("cpu") and requests.get("memory") and limits.get("cpu") and limits.get("memory"))

def _safe_k8s_get(path: str) -> dict:
