def __call__(
    self, position_ids: mx.array, dtype: mx.Dtype
) -> tuple[mx.array, mx.array]:
    """Return cos/sin tensors for ``position_ids`` of shape ``(B, 3, L)``."""
    pos = position_ids.astype(mx.float32).transpose(1, 0, 2)[..., None]
    freqs = pos * self._inv_freq[None, None, None, :]
    freqs_t = freqs[0]
    for dim, mask in enumerate(self._overwrite_masks, start=1):
        freqs_t = mx.where(mask, freqs[dim], freqs_t)

    emb = mx.concatenate([freqs_t, freqs_t], axis=-1)
    return mx.cos(emb).astype(dtype), mx.sin(emb).astype(dtype)

def _gqa_disabled_kwargs(ctx: PagedAttentionContext, ops: Any) -> dict[str, Any]:
    """The GQA kill switch for any native call, gated on build support."""
    if ctx.paged_native_capabilities is None:
        ctx.paged_native_capabilities = paged_attention_capabilities(ops)
    capabilities = ctx.paged_native_capabilities
    if not ctx.gqa_disabled:
        return {}
    if capabilities["gqa_disable"]:
        return {"gqa_disabled": True}
    if capabilities["gqa_decode"]:
        # Never silently ignore a kill switch on an unrecognized GQA build.
        raise RuntimeError(
            "Loaded native GQA build does not advertise disable support; "
            "rebuild the vllm-metal native extension."
        )
    # Pre-GQA native builds already use the established attention path.
    return {}

def main() -> None:
    sampling_params = SamplingParams(
        temperature=TEMPERATURE, top_k=TOP_K, top_p=TOP_P, min_p=MIN_P
    )
    for batch in (1, 8):
        logits_mx = mx.random.normal((batch, VOCAB_SIZE), key=mx.random.key(0))
        mx.eval(logits_mx)

        torch_ms = _time_torch(logits_mx, batch)
        native_ms = _time_native(logits_mx, [sampling_params] * batch)
        print(
            f"batch={batch} vocab={VOCAB_SIZE}: "
            f"torch CPU {torch_ms:.2f} ms, native MLX {native_ms:.2f} ms (sync)"
        )

def embed_tokens(self, input_ids: mx.array) -> mx.array:
    """Return the language model's input embeddings for ``input_ids``.

    Construct via :meth:`from_loaded_model` so the callable is resolved
    at load time; manually built instances must pass ``embed_tokens_fn``.
    """
    if self._embed_tokens_fn is None:
        raise RuntimeError(
            "embed_tokens_fn not resolved; construct via "
            "Qwen3VLMultimodalAdapter.from_loaded_model so the language "
            "model embedding path is sniffed at load time."
        )
    return self._embed_tokens_fn(input_ids)

