@lru_cache(maxsize=len(FWHT_SUPPORTED_HEAD_DIMS))
def get_fwht_signs(head_dim: int) -> mx.array:
    """Signs shared by Python FWHT and fused page materialization."""
    if head_dim not in FWHT_SUPPORTED_HEAD_DIMS:
        raise ValueError(
            f"FWHT only supports head_dim in {FWHT_SUPPORTED_HEAD_DIMS}, "
            f"got {head_dim}. "
            "The Metal kernel has hardcoded sign tables only for these sizes."
        )
    sign01 = mx.random.randint(0, 2, shape=(head_dim,), key=_RNG_KEY)
    return 1 - 2 * sign01

@staticmethod
def is_weights_path(value: str) -> bool:
    return value.endswith(_GGUF_SUFFIX)

@classmethod
def from_request(
    cls, sampling_params: SamplingParams | None, sampler: Sampler
) -> STTSampling:
    """Build the sampling a request asked for, greedy when it asked for none."""
    # A decode with no request behind it has no token budget either, so the
    # stand-in must not import ``SamplingParams``' own ``max_tokens`` default.
    params = sampling_params or SamplingParams(temperature=0.0, max_tokens=None)
    return cls(
        sampling_params=params,
        generator=create_request_generator(params),
        sampler=sampler,
    )

@classmethod
def _to_array(cls, piece: ExpertSlice, raw: bytes) -> mx.array:
    np_dtype, mx_dtype = cls.DTYPES[piece.location.dtype]
    array = mx.array(np.frombuffer(raw, dtype=np_dtype).reshape(piece.shape))
    return array.view(mx_dtype) if array.dtype != mx_dtype else array

def artifact(self, snapshot_id: str, kind: str, artifact_id: str) -> bytes:
    directory = self._snapshot_dir(snapshot_id)
    if not re.fullmatch(r"[a-f0-9]{32}", artifact_id):
        raise DesignError("InvalidArtifact", "Invalid artifact identifier.")
    if kind == "preview":
        path = directory / f"preview-{artifact_id}.png"
    elif kind == "bundle":
        path = directory / "exports" / artifact_id / "bundle.zip"
    else:
        raise DesignError("InvalidArtifact", "Unsupported artifact kind.")
    if not path.is_file():
        raise DesignError("ArtifactMissing", "Generate this artifact first.")
    return path.read_bytes()

def fix_html_files(directory: str):
    """修复HTML文件"""
    html_files = list(Path(directory).glob("*.html"))

    for html_path in html_files:
        with open(html_path, 'r', encoding='utf-8') as f:
            content = f.read()

        soup = BeautifulSoup(content, 'html.parser')

        # 替换data-src
        for tag in soup.find_all(['img', 'script']):
            if tag.has_attr('data-src'):
                tag['src'] = tag['data-src']
                del tag['data-src']

        for tag in soup.find_all('link'):
            if tag.has_attr('data-src'):
                tag['href'] = tag['data-src']
                del tag['data-src']

        # 移除body隐藏样式
        body = soup.find('body')
        if body and body.has_attr('style'):
            style = body['style']
            style = re.sub(r'display\s*:\s*none\s*;?', '', style)
            style = re.sub(r'opacity\s*:\s*0\s*;?', '', style)
            style = style.strip()
            if style:
                body['style'] = style
            else:
                del body['style']

        # 移除蓝湖脚本
        for script in soup.find_all('script'):
            if script.string and 'alistatic.lanhuapp.com' in script.string:
                script.decompose()

        # 添加映射函数
        head = soup.find('head')
        if head:
            mapping_script = soup.new_tag('script')
            mapping_script.string = '''
// 蓝湖Axure映射数据处理函数
function lanhu_Axure_Mapping_Data(data) {
