def _extent(solid):
    """Rough size of the solid, so a through-cut really goes through."""
    bb = solid.BoundingBox()
    return math.sqrt(bb.xlen ** 2 + bb.ylen ** 2 + bb.zlen ** 2)

def classify(rc, stdout):
    """(class, metrics or None) of one build's output."""
    res = next((ln for ln in reversed(stdout.splitlines()) if ln.startswith("RESULT ")), None)
    if res is not None:
        m = ast.literal_eval(res[7:].split(" radii ")[0])
        ok = (m["valid"] and m["solids"] == 1 and m["free_edges"] == 0 and abs(m["dv_pct"]) <= MAX_DV_PCT
              and m["dist_p95"] <= MAX_P95_REL * m["diag"])
        return ("pass" if ok else "unsound"), m
    fail = next((ln for ln in reversed(stdout.splitlines()) if ln.startswith("FAIL ")), "")
    if rc is None:
        return "timeout", None
    for key, cls in (("open or non-manifold", "open"), ("corners where", "corners"), ("do not meet there", "chain"),
                     ("lie on no fitted surface", "unlabelled"), ("free edges after sewing", "unsound")):
        if key in fail:
            return cls, None
    return "unsound", None

def reverse(stl):
    m = trimesh.load(stl, force="mesh")
    tri = np.asarray(m.triangles, float)
    lo, hi = m.bounds
    ax = pick_axis(tri, lo, hi)
    sil = silhouette(tri, ax)
    if sil.geom_type != "Polygon":                              # several islands: keep the largest (report it)
        sil = max(sil.geoms, key=lambda g: g.area)
    # only drop collinear/duplicate points: a coarser simplify turns arcs into chords before they are fitted
    sil = sil.simplify(1e-6 * float(np.linalg.norm(hi - lo)), preserve_topology=True)
    A_sil, P_sil = sil.area, sil.length
    outer = np.asarray(sil.exterior.coords)[:-1]
    holes = [np.asarray(i.coords)[:-1] for i in sil.interiors if Polygon(i).area > 1e-3 * A_sil]
    r_top, r_bot = (cap_round(m, ax, lo, hi, sil, c) for c in (+1, -1))
    if r_top is None:
        r_top = {"outer": fit_round(m, ax, lo, hi, A_sil, P_sil, +1), "holes": 0.0}
    if r_bot is None:
        r_bot = {"outer": fit_round(m, ax, lo, hi, A_sil, P_sil, -1), "holes": 0.0}
    H = float(hi[ax] - lo[ax])
    plane = {0: "YZ", 1: "XZ", 2: "XY"}[ax]
    R = {"axis": "XYZ"[ax], "plane": plane, "z0": float(lo[ax]), "height": H, "outer": outer, "holes": holes,
         "r_top": r_top, "r_bottom": r_bot, "silhouette_area": A_sil, "levels": []}
    zs = level_heights(m, ax, lo, hi, 1e-3 * A_sil)
    if len(zs) > 2:                                           # a stack of extrusions: one sketch per level
        for z0, z1 in zip(zs[:-1], zs[1:]):
            shapes = level_section(m, ax, (z0 + z1) / 2)
            if not shapes:
                continue
            prev = R["levels"][-1] if R["levels"] else None
            if prev and abs(prev["z1"] - z0) < 1e-9 and same_shapes(prev["shapes"], shapes):
                prev["z1"] = z1                               # the same sketch continues: one extrusion, no slivers
            else:
                R["levels"].append({"z0": z0, "z1": z1, "shapes": shapes})
        if len(R["levels"]) == 1:                             # it was one prism after all: the silhouette path
            R["levels"] = []
    return R

def sharp_points(clean, owner, step):
    """Points every `step` along the CAD's sharp edges (dihedral > 30 deg between two different
    B-rep faces)."""
    adj, angs = clean.face_adjacency, clean.face_adjacency_angles
    sharp = (angs > np.radians(30)) & (owner[adj[:, 0]] != owner[adj[:, 1]])
    pts = []
    for a, b in clean.vertices[clean.face_adjacency_edges[sharp]]:
        k = max(1, int(np.linalg.norm(b - a) / step))
        pts.append(a + np.outer(np.arange(k) / k, b - a))
    return np.vstack(pts) if pts else np.zeros((0, 3))

def _line_dev(P):
    a, b = P[0], P[-1]; ab = b - a; lab = np.linalg.norm(ab)
    if lab < 1e-9:
        return 1e9
    return float(np.abs((P[:, 0] - a[0]) * ab[1] - (P[:, 1] - a[1]) * ab[0]).max() / lab)

def section(tri, z):
    segs = []
    for t in tri:
        d = t[:, 2] - z
        pts = []
        for i in range(3):
            a, b = t[i], t[(i + 1) % 3]; da, db = d[i], d[(i + 1) % 3]
            if (da < 0) != (db < 0):
                s = da / (da - db); pts.append(a[:2] + s * (b[:2] - a[:2]))
        if len(pts) == 2:
            segs.append((pts[0], pts[1]))
    return segs

def _frame(plane):
    """(origin, normal, xdir, ydir) of a cq.Plane, as cq.Vector."""
    o = _V(*plane.origin.toTuple())
    n = _V(*plane.zDir.toTuple()).normalized()
    x = _V(*plane.xDir.toTuple()).normalized()
    return o, n, x, n.cross(x)

def to3d(p2, ax, h):
    v = [0.0, 0.0, 0.0]; o = [i for i in range(3) if i != ax]
    v[o[0]], v[o[1]], v[ax] = p2[0], p2[1], h
    return gp_Pnt(*v)

