    low_indicators = ["不确定", "可能", "疑似", "unclear", "might", "possibly"]
    for indicator in low_indicators:
        if indicator in text.lower():
            return "low"
    return "high"

def _tool_result_block(self, tool_use_id: str, result: Any, err: Exception | None) -> dict:
    if err is None:
        result, structured_truncated, total_count = self._bounded_value(
            result, max_rows=self._cfg.max_tool_result_rows
        )
        # Stringify unless already a string — the API accepts both but
        # models read plain text better.
        if isinstance(result, str):
            content = result
        else:
            try:
                content = json.dumps(result, ensure_ascii=False)
            except (TypeError, ValueError):
                content = str(result)
        if len(content) > self._cfg.max_tool_result_chars:
            omitted = len(content) - self._cfg.max_tool_result_chars
            content = (
                content[: self._cfg.max_tool_result_chars]
                + f"\n…[tool result truncated; {omitted} chars omitted]"
            )
            structured_truncated = True
        block = {
            "type": "tool_result",
            "tool_use_id": tool_use_id,
            "content": content,
        }
        if structured_truncated:
            block["_datamind_truncated"] = True
            if total_count is not None:
                block["_datamind_total_count"] = total_count
        return block
    return {
        "type": "tool_result",
        "tool_use_id": tool_use_id,
        "is_error": True,
        "content": f"{type(err).__name__}: {err}",
    }

def run_worker(args, runtime, result, crash_stage="none"):
    command = [sys.executable, "-m", "benchmark.robustness", "_build_worker",
               "--source", args.source, "--runtime", str(runtime), "--worker-result", str(result),
               "--surfaces", args.surfaces, "--crash-stage", crash_stage, "--after", str(args.after)]
    if args.fixture:
        command.append("--fixture")
    if args.questions:
        command.extend(["--questions", args.questions])
    if args.graph_sources:
        command.extend(["--graph-sources",args.graph_sources])
    with result.with_suffix(".log").open("w") as log:
        return subprocess.run(command, cwd=REPO, env={**os.environ, "PYTHONPATH": str(REPO)},
                              stdout=log, stderr=log, timeout=args.worker_timeout_s).returncode

def _atomic_json(path: Path, value: Any, *, overwrite: bool = True) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(f'.{path.name}.{uuid.uuid4().hex}.tmp')
    try:
        with temporary.open('w', encoding='utf-8') as handle:
            json.dump(value, handle, ensure_ascii=False, default=str)
            handle.flush()
            os.fsync(handle.fileno())
        if overwrite:
            os.replace(temporary, path)
        else:
            try:
                os.link(temporary, path)
            except FileExistsError:
                pass
    finally:
        temporary.unlink(missing_ok=True)

