def joint_mirror(env: ManagerBasedRLEnv, asset_cfg: SceneEntityCfg, mirror_joints: list[list[str]]) -> torch.Tensor:
    # extract the used quantities (to enable type-hinting)
    asset: Articulation = env.scene[asset_cfg.name]
    if not hasattr(env, "joint_mirror_joints_cache") or env.joint_mirror_joints_cache is None:
        # Cache joint positions for all pairs
        env.joint_mirror_joints_cache = [
            [asset.find_joints(joint_name) for joint_name in joint_pair] for joint_pair in mirror_joints
        ]
    reward = torch.zeros(env.num_envs, device=env.device)
    # Iterate over all joint pairs
    for joint_pair in env.joint_mirror_joints_cache:
        # Calculate the difference for each pair and add to the total reward
        diff = torch.sum(
            torch.square(asset.data.joint_pos[:, joint_pair[0][0]] - asset.data.joint_pos[:, joint_pair[1][0]]),
            dim=-1,
        )
        reward += diff
    reward *= 1 / len(mirror_joints) if len(mirror_joints) > 0 else 0
    reward *= torch.clamp(-env.scene["robot"].data.projected_gravity_b[:, 2], 0, 0.7) / 0.7
    return reward * get_gait_level_tensor(env)

def get_full_frame_batch(self, batch_size: int) -> torch.Tensor:
    """Sample a batch of full motion frames."""
    if self.preload_transitions:
        idxs = torch.randint(0, self.preloaded_s[0].shape[0], (batch_size,), device=self.device)
        return self.preloaded_s[0][idxs]
    else:
        traj_idxs = self.weighted_traj_idx_sample_batch(batch_size)
        times = self.traj_time_sample_batch(traj_idxs, self.num_frames)
        return self.get_full_frame_at_time_batch(traj_idxs, times)

def disable_zero_weight_rewards(self):
    """Set rewards with zero weight to None to skip computation."""
    for attr in dir(self.rewards):
        if not attr.startswith("__"):
            reward_attr = getattr(self.rewards, attr)
            if (
                not callable(reward_attr)
                and hasattr(reward_attr, "weight")
                and reward_attr.weight == 0
            ):
                setattr(self.rewards, attr, None)

def normalize(self, input: torch.Tensor) -> torch.Tensor:
    return torch.clamp(
        (input - self.mean) / torch.sqrt(self.var + self.epsilon),
        -self.clip_obs, self.clip_obs
    ).to(torch.float32)

def joint_torques_l2(env: ManagerBasedRLEnv, asset_cfg: SceneEntityCfg = SceneEntityCfg("robot")) -> torch.Tensor:
    """Penalize joint torques (curriculum-scaled by gait_level)."""
    asset: Articulation = env.scene[asset_cfg.name]
    reward = torch.sum(torch.square(asset.data.applied_torque[:, asset_cfg.joint_ids]), dim=1)
    return reward * get_gait_level_tensor(env)

