def generate_policy_query_cases(target: int = 50) -> list[dict]:
    labels = ["policy_query", "tax_service", "business_register", "fund_query"]
    cases: list[dict] = []
    idx = 1
    for label_id in labels:
        qs = _generate_label_queries(label_id, max(5, target // 4))
        for q in qs:
            cases.append({
                "id": f"policy_{idx:04d}",
                "query": q,
                "expected_intent": label_id,
                "expected_answer": random.choice(
                    _RAG_ANSWERS.get(label_id, [["政策", "补贴"]])
                ),
            })
            idx += 1
            if idx > target:
                break
        if idx > target:
            break
    return cases[:target]

def score(self, query: str) -> list[float]:
    """
    计算查询与所有文档的相关性分数。

    Args:
        query: 查询文本

    Returns:
        与文档一一对应的分数列表（无匹配返回 0）
    """
    if not self._documents:
        return []

    query_tokens = _tokenize(query)
    if not query_tokens:
        return [0.0] * self._doc_count

    scores = np.zeros(self._doc_count, dtype=np.float32)

    for term in set(query_tokens):
        idf = self._idf(term)
        if idf <= 0:
            continue

        for i, freq in enumerate(self._doc_freqs):
            tf = freq.get(term, 0)
            if tf == 0:
                continue

            dl = self._doc_lengths[i]
            denominator = tf + self._k1 * (
                1 - self._b + self._b * dl / self._avgdl
            ) if self._avgdl > 0 else tf + self._k1
            scores[i] += idf * (tf * (self._k1 + 1)) / denominator

    return scores.tolist()

def _extract_final_answer(output_data) -> str | None:
    """
    从 Agent 输出中提取 final_answer。

    支持 JSON 字符串或纯文本。
    """
    if not output_data:
        return None
    if isinstance(output_data, dict):
        return output_data.get("final_answer") or output_data.get("answer")

    try:
        parsed = json.loads(output_data)
        if isinstance(parsed, dict):
            return parsed.get("final_answer") or parsed.get("answer")
    except (json.JSONDecodeError, TypeError):
        pass
    return output_data if isinstance(output_data, str) else None

